const $=s=>document.querySelector(s);
const paths={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',projects:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',requirements:'<path d="M5 3h10l4 4v14H5Z"/><path d="M9 11h6M9 15h6M9 7h2"/>',teams:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5"/>',workspaces:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 9h18M9 9v12"/>',users:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',roles:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',permissions:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',bell:'<path d="M6 9a6 6 0 0 1 12 0v7l2 2H4l2-2ZM10 21h4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',logout:'<path d="M10 3H4v18h6M10 12h11m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 4v16M4 12h16"/>'};
function icon(n){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[n]||paths.projects)+'</svg>'}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let profile={name:'Sahim Chy',email:'sahim@example.com',title:'Product owner'},workspace=0,screen='dashboard',reqTab=0,selected=1,sourceTab=0,filter='';
let spaces=[{id:0,name:'JB Connect',desc:'Product discovery and client delivery'},{id:1,name:'Innovation Lab',desc:'Ideas, experiments, and new products'}];
let teams=[{id:1,name:'Product & Design',desc:'Discovery, experience, and requirements',space:0,members:[1,2]},{id:2,name:'Engineering',desc:'Technical discovery and feasibility',space:0,members:[3,4]},{id:3,name:'Client Success',desc:'Stakeholder communication and reviews',space:0,members:[5]}];
let users=[{id:1,name:'Sahim Chy',email:'sahim@example.com',role:'Owner',status:'Active',space:0},{id:2,name:'Maya Chen',email:'maya@example.com',role:'Admin',status:'Active',space:0},{id:3,name:'Alex Morgan',email:'alex@example.com',role:'Editor',status:'Active',space:0},{id:4,name:'Daniel Kim',email:'daniel@example.com',role:'Editor',status:'Active',space:0},{id:5,name:'Sarah Wilson',email:'sarah@example.com',role:'Reviewer',status:'Active',space:0}];
let projects=[{id:1,name:'Northstar Client Portal',desc:'A simpler way to collaborate with clients',team:1,status:'In review',progress:72,space:0},{id:2,name:'Commerce Platform',desc:'Connected shopping experiences',team:2,status:'Draft',progress:38,space:0},{id:3,name:'Employee Hub',desc:'One home for internal services',team:1,status:'Approved',progress:100,space:0},{id:4,name:'Service Desk',desc:'Faster support for every customer',team:3,status:'Clarifying',progress:24,space:0}];
let roles=['Owner','Admin','Editor','Reviewer','Viewer'],rights=['View projects','Create projects','Edit requirements','Approve baselines','Manage teams','Manage users','Manage roles'];
let perms=roles.map((r,i)=>rights.map((_,j)=>i===0||i===1||i===2&&j<3||i===3&&(j===0||j===3)||i===4&&j===0));
let reqs={};const activities=[['MC','Maya Chen','requested a review','Northstar Client Portal','12 minutes ago'],['AM','Alex Morgan','added meeting notes','Commerce Platform','38 minutes ago'],['SC','Sahim Chy','approved the baseline','Employee Hub','2 hours ago'],['DK','Daniel Kim','joined the team','Engineering','3 hours ago']];
function initial(p){return {brief:'We need '+p.name.toLowerCase()+'. '+p.desc+'. Users should securely access their assigned projects, review deliverables, and provide feedback. Project managers need milestones and progress updates.',meeting:'Product owner: We need clear ownership for approvals.\nProject manager: Notifications should keep stakeholders informed.\nOpen question: Who can approve a deliverable?',answers:['',''],doc:'',approved:p.status==='Approved',reviewed:false,applied:false,source:'Project brief'}}
function current(){let p=projects.find(p=>p.id===selected);if(!p){p=projects.find(p=>p.space===workspace);if(!p)return null;selected=p.id}return reqs[selected]??(reqs[selected]=initial(p))}
const initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('');
const avatar=n=>'<span class="avatar">'+esc(initials(n))+'</span>';
const badge=s=>'<span class="badge '+({Approved:'green',Active:'green','In review':'amber',Clarifying:'blue',Draft:'gray',Suspended:'gray'}[s]||'')+'">'+esc(s)+'</span>';
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3500)}
function navigate(s){captureReq();screen=s;filter='';document.body.classList.remove('menu-open');history.replaceState(null,'','#'+s);render()}
function heading(t,s,action=''){return '<div class="page-head"><div><h1>'+t+'</h1><p class="sub">'+s+'</p></div><div class="actions">'+action+'</div></div>'}
function button(t,action,primary=false){return '<button class="'+(primary?'primary':'')+'" onclick="'+action+'">'+t+'</button>'}
function table(heads,rows){return '<div class="table-wrap"><table><thead><tr>'+heads.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'+(rows.length?'':'<div class="empty">No matching items in this workspace.</div>')}
function panel(t,body,action='',sub=''){return '<section class="panel"><div class="panel-title"><div><h2>'+t+'</h2>'+(sub?'<small>'+sub+'</small>':'')+'</div>'+action+'</div>'+body+'</section>'}
function workspaceProjects(){return projects.filter(p=>p.space===workspace&&p.name.toLowerCase().includes(filter.toLowerCase()))}
function projectTable(){return table(['Project name','Status','Progress','Team',''],workspaceProjects().map(p=>['<a class="project-cell" href="#requirements" onclick="event.preventDefault();openProject('+p.id+')"><span class="tile-icon">'+icon('projects')+'</span><span>'+esc(p.name)+'<small>Requirements → Planning → Architecture</small></span></a>',badge(p.status),'<span class="progress-line"><i style="width:'+p.progress+'%"></i></span><small>'+p.progress+'%</small>','<div class="members">'+(teams.find(t=>t.id===p.team)?.members||[]).slice(0,3).map(id=>avatar(users.find(u=>u.id===id)?.name||'New Member')).join('')+'</div>',button('Open','openProject('+p.id+')')]))}
function dashboard(){let ps=workspaceProjects(),us=users.filter(u=>u.space===workspace);return heading('Good morning, '+esc(profile.name.split(' ')[0])+' ✦','Here’s what’s happening across your workspace.',button(icon('plus')+' New project',"openCreate('project')",true))+'<div class="metrics">'+[['Total projects',ps.length,'projects','Across this workspace'],['Requirements',ps.length*3,'requirements','Illustrative sample count'],['Pending reviews',ps.filter(p=>p.status==='In review').length,'bell','Ready for your attention'],['Team members',us.length,'teams','Working together']].map(([t,n,i,b])=>'<div class="metric"><div class="metric-top">'+t+'<span class="metric-icon">'+icon(i)+'</span></div><strong>'+n+'</strong><small>'+b+'</small></div>').join('')+'</div><div class="columns"><div>'+panel('Recent projects',projectTable(),'<a class="text-link" href="#projects">View all projects '+icon('arrow')+'</a>','Your projects, from discovery to approval')+'<div class="bottom-grid">'+panel('Your review queue',ps.filter(p=>p.status==='In review').map(p=>'<div class="task"><span class="tile-icon">'+icon('requirements')+'</span><div><strong>'+esc(p.name)+'</strong><small>Requirements need your review</small><button class="text-link" onclick="openProject('+p.id+');reqTab=3;render()">Review now →</button></div></div>').join('')||'<div class="empty">You’re all caught up.</div>')+panel('Baseline overview','<div class="health"><div class="donut" style="background:conic-gradient(#9578dd 0 '+(ps.length?ps.filter(p=>p.status==='Approved').length/ps.length*100:0)+'%,#f0edf8 0)"><div>'+ps.filter(p=>p.status==='Approved').length+'<small>approved</small></div></div><div class="legend"><p>Approved <b>'+ps.filter(p=>p.status==='Approved').length+'</b></p><p>In progress <b>'+ps.filter(p=>p.status!=='Approved').length+'</b></p><p>Total projects <b>'+ps.length+'</b></p></div></div><div class="mini-callout">Every baseline requires a human review and approval.</div>')+'</div></div>'+panel('Recent activity','<div class="activity">'+(workspace===0?activities:[]).map(([a,n,v,p,t])=>'<div class="event"><span class="avatar">'+a+'</span><div><b>'+esc(n)+'</b> '+v+'<br><b>'+esc(p)+'</b><small>'+t+' · Sample</small></div></div>').join('')+'</div>','','Example workspace activity').replace('class="panel"','class="panel activity-panel"')+'</div>'}
function listProjects(){return heading('Projects','Organize discovery. Build a clear requirements baseline.',button('+ New project',"openCreate('project')",true))+panel('All projects','<div class="toolbar"><input class="filter" aria-label="Search projects" placeholder="Search projects…" value="'+esc(filter)+'" oninput="filter=this.value;document.getElementById(\'projectRows\').innerHTML=projectTable()"><span class="badge">'+spaces[workspace].name+'</span></div><div id="projectRows">'+projectTable()+'</div>')}
function openProject(id){selected=id;reqTab=0;navigate('requirements')}
function workspaceScreen(){return heading('Workspaces','A shared home for your people and projects.',button('+ New workspace',"openCreate('workspace')",true))+'<div class="cards">'+spaces.map(w=>'<section class="card"><span class="tile-icon">'+icon('workspaces')+'</span><h2>'+esc(w.name)+'</h2><p>'+esc(w.desc)+'</p><span class="badge '+(w.id===workspace?'':'gray')+'">'+(w.id===workspace?'Current workspace':'Workspace')+'</span><div class="card-footer"><span>'+projects.filter(p=>p.space===w.id).length+' projects · '+users.filter(u=>u.space===w.id).length+' members</span>'+button('Open','switchWorkspace('+w.id+')')+'</div></section>').join('')+'</div>'}
function switchWorkspace(id){workspace=id;selected=projects.find(p=>p.space===id)?.id||0;navigate('dashboard')}
function teamScreen(){return heading('Teams','Bring the right people together for every project.',button('+ Create team',"openCreate('team')",true))+'<div class="cards">'+teams.filter(t=>t.space===workspace).map(t=>'<section class="card"><span class="tile-icon">'+icon('teams')+'</span><h2>'+esc(t.name)+'</h2><p>'+esc(t.desc)+'</p><div class="members">'+t.members.map(id=>avatar(users.find(u=>u.id===id)?.name||'User')).join('')+'</div><div class="card-footer"><span>'+t.members.length+' members</span>'+button('Manage team','manageTeam('+t.id+')')+'</div></section>').join('')+'</div>'}
function userScreen(){return heading('User management','Manage who belongs to this workspace and what they can access.',button('+ Add user',"openCreate('user')",true))+panel('Workspace members',table(['Name','Role','Status','Actions'],users.filter(u=>u.space===workspace).map(u=>['<div class="project-cell">'+avatar(u.name)+'<span>'+esc(u.name)+'<small>'+esc(u.email)+'</small></span></div>','<select aria-label="Role for '+esc(u.name)+'" onchange="changeRole('+u.id+',this.value)" '+(u.id===1?'disabled':'')+'>'+roles.map(r=>'<option '+(r===u.role?'selected':'')+'>'+esc(r)+'</option>').join('')+'</select>',badge(u.status),u.id===1?'<span class="sub">Workspace owner</span>':button(u.status==='Active'?'Suspend':'Activate','toggleUser('+u.id+')')])),'','Changes are simulated in this UI session')}
function changeRole(id,r){users.find(u=>u.id===id).role=r;toast('User role updated in this session.')}
function toggleUser(id){const u=users.find(u=>u.id===id);u.status=u.status==='Active'?'Suspended':'Active';render()}
function roleScreen(){return heading('Roles','Define responsibilities for everyone in the workspace.',button('+ Create role',"openCreate('role')",true))+'<div class="cards">'+roles.map((r,i)=>'<section class="card"><span class="tile-icon">'+icon('roles')+'</span><h2>'+esc(r)+'</h2><p>'+['Full workspace ownership and administration.','Manage projects, teams, and workspace access.','Create and refine project requirements.','Review requirements and approve baselines.','Read project information and approved documents.'][i%5]+'</p><span class="badge">'+perms[i].filter(Boolean).length+' permissions</span><div class="card-footer"><span>'+users.filter(u=>u.role===r&&u.space===workspace).length+' members</span><a class="text-link" href="#permissions">View permissions →</a></div></section>').join('')+'</div>'}
function permissionsScreen(){return heading('Permissions','Configure access by role. The owner always retains full access.')+panel('Role permission matrix',table(['Permission',...roles],rights.map((r,j)=>[r,...roles.map((role,i)=>'<input type="checkbox" aria-label="'+esc(role+' '+r)+'" '+(perms[i][j]?'checked':'')+' '+(i===0?'disabled':'')+' onchange="perms['+i+']['+j+']=this.checked">')]))+'<div class="form-footer">'+button('Save permissions',"toast('Permission settings kept in this demo session.')",true)+'</div>','','UI configuration only. Server-side enforcement is not connected.')}
function profileScreen(){return heading('My profile','Your personal information and account details.')+'<div class="settings-grid"><section class="panel profile-card">'+avatar(profile.name)+'<h2>'+esc(profile.name)+'</h2><p class="sub">'+esc(profile.title)+'</p><p>'+badge('Owner')+'</p><a class="text-link" href="#login">View login screen →</a></section><form class="panel" onsubmit="saveProfile(event)"><div class="panel-title"><h2>Personal information</h2></div><div class="form form-grid">'+field('Full name','name',profile.name)+field('Job title','title',profile.title)+field('Email address','email',profile.email,'email')+'<label class="field">Workspace<input value="'+esc(spaces[workspace].name)+'" disabled></label></div><div class="form-footer"><button class="primary">Save changes</button></div></form></div>'}
function saveProfile(e){e.preventDefault();const f=new FormData(e.target);profile=Object.fromEntries(f);users[0].name=profile.name;users[0].email=profile.email;render();toast('Profile updated in this session.')}
function field(label,name,value='',type='text'){return '<label class="field">'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" required></label>'}
function modal(title,body,submit){$('#modal').innerHTML='<form onsubmit="'+submit+'"><h2>'+title+'</h2><div class="form">'+body+'</div><div class="form-footer"><button type="button" onclick="document.getElementById(\'modal\').close()">Cancel</button><button class="primary">Save</button></div></form>';$('#modal').showModal()}
function openCreate(type){let body=field(type==='user'?'Full name':'Name','name');if(type==='user')body+=field('Email address','email','','email')+'<label class="field">Role<select name="role">'+roles.filter(r=>r!=='Owner').map(r=>'<option>'+esc(r)+'</option>').join('')+'</select></label>';if(['team','workspace','project'].includes(type))body+=field('Description','desc');if(type==='project')body+='<label class="field">Team<select name="team"><option value="0">Unassigned</option>'+teams.filter(t=>t.space===workspace).map(t=>'<option value="'+t.id+'">'+esc(t.name)+'</option>').join('')+'</select></label>';modal('Create '+type,body,"createItem(event,'"+type+"')")}
function createItem(e,type){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!f.name.trim())return;let id=Date.now();if(type==='project')projects.push({id,name:f.name,desc:f.desc,team:Number(f.team),space:workspace,status:'Draft',progress:0});if(type==='team')teams.push({id,name:f.name,desc:f.desc,space:workspace,members:[]});if(type==='workspace')spaces.push({id:spaces.length,name:f.name,desc:f.desc});if(type==='user'){if(users.some(u=>u.email===f.email&&u.space===workspace)){toast('This email is already in the workspace.');return}users.push({id,...f,status:'Active',space:workspace})}if(type==='role'){if(roles.includes(f.name)){toast('That role already exists.');return}roles.push(f.name);perms.push(rights.map((_,i)=>i===0))}$('#modal').close();render();toast('Created in this prototype session.')}
function manageTeam(id){let t=teams.find(t=>t.id===id);modal('Manage '+esc(t.name),users.filter(u=>u.space===workspace).map(u=>'<label class="field" style="flex-direction:row"><input type="checkbox" name="member" value="'+u.id+'" '+(t.members.includes(u.id)?'checked':'')+'>'+esc(u.name)+'</label>').join(''),"saveTeam(event,"+id+")")}
function saveTeam(e,id){e.preventDefault();teams.find(t=>t.id===id).members=new FormData(e.target).getAll('member').map(Number);$('#modal').close();render();toast('Team members updated.')}
function captureReq(){let r=reqs[selected];if(!r)return;if($('#brief'))r.brief=$('#brief').value;if($('#meeting'))r.meeting=$('#meeting').value;if($('#ans0'))r.answers=[$('#ans0').value,$('#ans1').value];if($('#srs'))r.doc=$('#srs').innerHTML}
function setTab(n){captureReq();reqTab=n;render()}
function generateDoc(r){if(r.doc)return;r.doc='<h3>1. Project overview</h3><p>'+esc(r.brief).replace(/\n/g,'<br>')+'</p><h3>2. Meeting context</h3><p>'+esc(r.meeting).replace(/\n/g,'<br>')+'</p><h3>3. Requirements · Illustrative draft</h3><p><b>FR-001 · Access control</b><br>Users may access only projects assigned to their organization.</p><p><b>FR-002 · Deliverable review</b><br>Assigned users may review deliverables and submit feedback.</p><p><b>FR-003 · Notifications</b><br>Notify assigned stakeholders when a deliverable is ready.</p><h3>4. Clarifications</h3><p>Approver: '+esc(r.answers[0]||'Open assumption requiring confirmation.')+'<br>Notification timing: '+esc(r.answers[1]||'Open assumption requiring confirmation.')+'</p>'}
function requirementScreen(){const p=projects.find(x=>x.id===selected&&x.space===workspace)||workspaceProjects()[0];if(!p)return heading('Requirements','Select or create a project to begin.')+button('+ Create project',"openCreate('project')",true);selected=p.id;const r=current();let body='',bottom='';
if(reqTab===0){body='<div class="tabs">'+['Project brief','Documents','Meeting'].map((x,i)=>button(x,'captureReq();sourceTab='+i+';render()')).join('')+'</div>'+(sourceTab===0?'<label class="field">What are we building?<textarea id="brief" '+(r.approved?'disabled':'')+'>'+esc(r.brief)+'</textarea></label>':sourceTab===1?'<label class="field">Add a supporting text document<input type="file" accept=".txt,.md" onchange="readFile(this)" '+(r.approved?'disabled':'')+'></label><p class="sub">TXT and Markdown files are read in your browser. PDF ingestion is not connected in this prototype.</p><p class="sample">'+esc(r.source)+'</p>':'<label class="field">Meeting transcript<textarea id="meeting" '+(r.approved?'disabled':'')+'>'+esc(r.meeting)+'</textarea></label><p class="sub">Paste meeting notes or a transcript. Live recording is not connected.</p>');bottom=button('Continue to clarification →','setTab(1)',true)}
if(reqTab===1){body=['Who can approve deliverables?','How quickly should notifications arrive?'].map((q,i)=>'<label class="field">'+q+'<textarea style="min-height:85px" id="ans'+i+'" '+(r.approved?'disabled':'')+'>'+esc(r.answers[i])+'</textarea></label>').join('');bottom=button('Skip with assumptions','setTab(2)')+button('Create sample SRS →','setTab(2)',true)}
if(reqTab===2){generateDoc(r);body='<div class="actions" style="justify-content:space-between;margin-bottom:20px">'+badge(r.approved?'Approved':'Draft')+'<span class="sub">'+(r.approved?'Read-only baseline':'Click the document to edit')+'</span></div><article id="srs" class="doc" contenteditable="'+!r.approved+'" aria-label="Software requirements specification">'+r.doc+'</article>';bottom=button('Save draft',"captureReq();toast('Draft kept in this session.')")+button('Review quality →','setTab(3)',true)}
if(reqTab===3){generateDoc(r);body='<p class="sub">Illustrative assessment, not a live AI quality score.</p>'+['Define a measurable notification target','Record approval ownership and an audit trail'].map(t=>'<div class="review-row"><b>'+t+'</b><p>Clarify this requirement with the stakeholders before implementation. You choose whether to add proposed wording.</p></div>').join('')+'<p>'+button(r.applied?'Recommendation added':'Apply proposed wording','applyRecommendation()')+'</p>';bottom=button('Back to document','setTab(2)')+button('Complete review →','current().reviewed=true;setTab(4)',true)}
if(reqTab===4){body='<div class="approval"><div class="tile-icon">'+icon(r.approved?'check':'roles')+'</div><h2>'+(r.approved?'Baseline approved':'Ready for your decision')+'</h2><p>'+(r.approved?'This version is locked for review and export.':'Review and approve this SRS to establish the project baseline.')+'</p>'+(r.approved?badge('Approved'):'<label><input id="approveCheck" type="checkbox" '+(!r.reviewed?'disabled':'')+'> I reviewed and approve this SRS.</label><p class="sub">'+(!r.reviewed?'Complete the quality review first.':'')+'</p>')+'</div>';bottom=r.approved?button('Create new draft','newDraft()'):button('Approve baseline','approveBaseline()',true)}
return heading(esc(p.name),'Phase 1 · Requirements baseline',button('↓ Export SRS','exportSrs()'))+'<div class="tabs">'+['Capture input','Clarification','SRS workspace','Quality review','Baseline'].map((t,i)=>'<button class="'+(reqTab===i?'selected':'')+'" onclick="setTab('+i+')">'+(i+1)+'. '+t+'</button>').join('')+'</div><div class="req-layout">'+panel(['Project context','Clarify the details','Software requirements specification','Requirement quality','Requirements baseline'][reqTab],'<div class="req-body">'+body+'</div><div class="form-footer">'+bottom+'</div>')+'<section class="panel req-aside"><div class="ai-panel"><span class="tile-icon">✦</span><h3>Requirements assistant</h3><p>Keep the original context close. Resolve uncertainty, refine the document, and approve only when your team is ready.</p><hr style="border:0;border-top:1px solid #eee"><h3>Project context</h3><p>'+esc(p.desc)+'</p><span class="badge">Human approval required</span><div class="sample">UI prototype<br>Sample AI output. Changes last for this session. No production AI or authentication is connected.</div></div></section></div>'}
async function readFile(input){let f=input.files[0];if(!f)return;if(f.size>1000000){toast('Choose a text file under 1 MB.');return}const r=current();r.brief+='\n\n'+await f.text();r.source=f.name;render();toast('Document added to the project brief.')}
function applyRecommendation(){const r=current();if(r.approved){toast('Create a new draft to change the baseline.');return}if(r.applied)return;r.doc+='<h3>Proposed additions requiring stakeholder confirmation</h3><p>Proposed: designate a client owner as the final approver. Record their decision and timestamp. Queue notification emails within five minutes and record failures.</p>';r.applied=true;render()}
function approveBaseline(){let r=current();if(!r.reviewed||!$('#approveCheck')?.checked){toast('Complete the review and confirm your approval.');return}r.approved=true;let p=projects.find(x=>x.id===selected);p.status='Approved';p.progress=100;render();toast('Baseline approved in this session.')}
function newDraft(){const r=current();r.approved=false;r.reviewed=false;projects.find(p=>p.id===selected).status='Draft';setTab(2)}
function exportSrs(){captureReq();const r=current();if(!r.doc){toast('Create the SRS first.');return}const url=URL.createObjectURL(new Blob(['<!doctype html><meta charset="utf-8"><title>SRS</title><h1>Software Requirements Specification</h1><p>'+(r.approved?'Approved baseline':'Draft')+'</p>'+r.doc],{type:'text/html'}));let a=document.createElement('a');a.href=url;a.download='requirements.html';a.click();URL.revokeObjectURL(url)}
function authScreen(register=false){return '<div class="auth"><section class="auth-art"><div class="brand"><span class="logo">b</span>blueprint</div><div><span class="badge">AI PRODUCT DEVELOPMENT</span><h1>Great products start with a shared understanding.</h1><p>A thoughtful workspace for your team, your ideas, and the requirements that connect them.</p></div><small>Requirements. Reviewed by people.</small></section><section class="auth-form"><h1>'+(register?'Create your account':'Welcome back')+'</h1><p class="sub">'+(register?'Set up your profile and explore your workspace.':'Sign in to your product workspace.')+'</p><form onsubmit="authSubmit(event,'+register+')">'+(register?field('Full name','name'):'')+field('Email address','email','','email')+'<label class="field">Password<input name="password" type="password" minlength="8" autocomplete="'+(register?'new-password':'current-password')+'" required></label><button class="primary">'+(register?'Create demo account':'Sign in to demo')+'</button></form><p class="center">'+(register?'Already have an account? <a href="#login">Sign in</a>':'New to Blueprint? <a href="#register">Create an account</a>')+'</p><p class="center"><a href="#dashboard">Explore the demo workspace →</a></p><div class="auth-note">Interactive UI preview. No real account is created or authenticated. Please use sample credentials. Passwords are not stored or sent.</div></section></div>'}
function authSubmit(e,register){e.preventDefault();const f=new FormData(e.target);if(register)profile.name=f.get('name');profile.email=f.get('email');e.target.reset();navigate('dashboard');toast(register?'Demo profile created.':'Demo workspace opened.')}
function render(){const auth=['login','register'].includes(screen);if(auth){$('#root').innerHTML=authScreen(screen==='register');return}let nav=[['dashboard','Dashboard'],['projects','Projects'],['requirements','01 · Requirements'],['planning','02 · Planning'],['architecture','03 · Architecture'],['meetings','Live meetings'],['usage','Usage'],['workspaces','Workspaces'],['teams','Teams'],['users','User management'],['roles','Roles'],['permissions','Permissions']];$('#root').innerHTML='<aside><a class="brand" href="#dashboard"><span class="logo">b</span>blueprint</a><button class="switcher" onclick="navigate(\'workspaces\')"><span class="ws-icon">'+esc(initials(spaces[workspace].name))+'</span><span><b>'+esc(spaces[workspace].name)+'</b><small>Workspace</small></span><span class="chevron">⌄</span></button><nav>'+nav.map(([k,n],i)=>(i===0?'<div class="group">WORKSPACE</div>':i===9?'<div class="group" style="margin-top:18px">ADMINISTRATION</div>':'')+'<a href="#'+k+'" class="'+(screen===k?'active':'')+'">'+icon(k)+n+(k==='projects'?'<span class="count">'+projects.filter(p=>p.space===workspace).length+'</span>':'')+'</a>').join('')+'</nav><div class="side-bottom"><div class="side-note"><b>Built around your team</b><p>Capture context. Refine together.<br>Approve with confidence.</p></div><div class="account"><a href="#profile">'+avatar(profile.name)+'</a><a href="#profile">'+esc(profile.name)+'<small>Workspace owner</small></a><button class="iconbtn" aria-label="Sign out to login preview" onclick="navigate(\'login\')">'+icon('logout')+'</button></div></div></aside><div class="layout"><header><div class="crumb"><button class="iconbtn mobile-menu" aria-label="Toggle navigation" onclick="document.body.classList.toggle(\'menu-open\')">☰</button>'+esc(spaces[workspace].name)+' <span>/</span> <b>'+esc(nav.find(x=>x[0]===screen)?.[1]||'My profile')+'</b></div><div class="header-right"><span class="demo-label">Demo workspace</span><button class="iconbtn" aria-label="Notifications" onclick="toast(\'Review the pending requirements in your dashboard.\')">'+icon('bell')+'</button><a href="#profile" aria-label="My profile">'+avatar(profile.name)+'</a></div></header><main>'+({dashboard,projects:listProjects,workspaces:workspaceScreen,teams:teamScreen,users:userScreen,roles:roleScreen,permissions:permissionsScreen,profile:profileScreen,requirements:requirementScreen,planning:()=>planningScreen(),architecture:()=>architectureScreen(),meetings:()=>meetingScreen(),usage:()=>usageScreen()}[screen]||dashboard)()+'<footer><span>Blueprint · AI Product Development Assistant</span><span>Interactive prototype · Session only</span></footer></main></div>'}
window.addEventListener('hashchange',()=>{captureReq();screen=location.hash.slice(1)||'dashboard';document.body.classList.remove('menu-open');render()});screen=location.hash.slice(1)||'dashboard';
if(document.modelContext?.registerTool)document.modelContext.registerTool({name:'navigate_blueprint_screen',description:'Open a screen in the Blueprint UI prototype. Does not authenticate or approve.',inputSchema:{type:'object',properties:{screen:{type:'string',enum:['dashboard','projects','requirements','planning','architecture','meetings','usage','workspaces','teams','users','roles','permissions','profile','login','register']}},required:['screen'],additionalProperties:false},execute(x){if(!['dashboard','projects','requirements','planning','architecture','meetings','usage','workspaces','teams','users','roles','permissions','profile','login','register'].includes(x.screen))throw Error('Unknown screen');navigate(x.screen);return{screen,demo:true}}});
